/* GradeLab, Resource Vault (+Notebook), Question Bank, InsideAUST */
(function () {
  const { I, esc, av, member, hero, tabs, sectionHead, masthead, card, empty, seg, bar, statCard, modal, toast, register, ACTS, MENUS, D } = P;
  const GP = { 'A+': 4, A: 3.75, 'A-': 3.5, 'B+': 3.25, B: 3, 'B-': 2.75, 'C+': 2.5, C: 2.25, D: 2, F: 0 };

  /* ───────────── GradeLab ───────────── */
  const GT = [{ id: 'cgpagraph', label: 'CGPA Calculator', icon: 'trending-up' }, { id: 'semestertracker', label: 'Semester Wise', icon: 'layers' }, { id: 'heatmap', label: 'Dept Heatmap', icon: 'grid-3x3' }, { id: 'bestworst', label: 'Best & Worst', icon: 'trophy' }, { id: 'prereqs', label: 'Prerequisites', icon: 'git-branch' }];
  function calcRows() {
    return D.courses.map((c, i) => `<tr><td><b>${c.code}</b><div class="faint" style="font-size:11px">${c.name}</div></td><td>${c.cr}</td><td><select class="input gsel" data-i="${i}" style="height:32px;width:84px">${Object.keys(GP).map((g) => `<option ${g === c.grade ? 'selected' : ''}>${g}</option>`).join('')}</select></td><td class="num gp">${GP[c.grade].toFixed(2)}</td></tr>`).join('');
  }
  function gpa() { const cr = D.courses.reduce((s, c) => s + c.cr, 0); return (D.courses.reduce((s, c) => s + GP[c.grade] * c.cr, 0) / cr).toFixed(2); }
  function gradelab(sub) {
    sub = sub || 'cgpagraph'; let b;
    if (sub === 'cgpagraph') b = `<div class="main-grid"><section class="card"><div class="card-h"><h3>${I('graduation-cap', 16)}This semester</h3><div class="r"><button class="btn sm" data-act="toast" data-msg="Course added">${I('plus', 13)}Course</button></div></div><div class="tscroll"><table class="table"><thead><tr><th>Course</th><th>Credit</th><th>Grade</th><th>GP</th></tr></thead><tbody>${calcRows()}</tbody></table></div><div class="dashed"></div><div class="row between"><span class="label">Semester GPA</span><span class="num ok" style="font-size:1.8rem" id="gpa">${gpa()}</span></div></section>
      <div class="stack">${statCard('Projected CGPA', '<span id="cg">3.62</span>', 'Based on 98 credits', 'target')}${card('CGPA trend', 'trending-up', P.spark(D.semesters.map((s) => s.g)) + `<div class="row between faint" style="font-size:11px;margin-top:6px">${D.semesters.map((s) => `<span>${s.s}</span>`).join('')}</div>`)}</div></div>`;
    else if (sub === 'semestertracker') b = `<div class="grid g3">${D.semesters.map((s, i) => `<section class="card hoverable" data-act="toast" data-msg="Semester ${s.s} details"><div class="row between"><span class="label">Semester ${s.s}</span>${i === 5 ? '<span class="chip amber">Current</span>' : ''}</div><div class="num" style="font-size:2rem;margin:8px 0">${s.g.toFixed(2)}</div>${bar(((s.g - 2) / 2) * 100)}<div class="faint" style="font-size:11px;margin-top:8px">${18 + (i % 3)} credits · ${6 + (i % 2)} courses</div></section>`).join('')}</div>`;
    else if (sub === 'heatmap') b = card('Average CGPA by department & batch', 'grid-3x3', `<div class="tscroll"><table class="table heat-t"><thead><tr><th>Dept</th>${['2019', '2020', '2021', '2022', '2023'].map((x) => `<th>${x}</th>`).join('')}</tr></thead><tbody>${['CSE', 'EEE', 'CE', 'ME', 'IPE', 'TE', 'ARCH', 'BBA'].map((d, r) => `<tr><td><b>${d}</b></td>${[0, 1, 2, 3, 4].map((c) => { const v = (3.05 + (((r * 7 + c * 3) % 9) / 10)).toFixed(2); return `<td><span class="hcell" style="--a:${(v - 3) * 100}%" title="${v}">${v}</span></td>`; }).join('')}</tr>`).join('')}</tbody></table></div>`);
    else if (sub === 'bestworst') b = `<div class="grid g2">${card('Most loved courses', 'thumbs-up', pollList([['CSE 3201 · Operating Systems', 82], ['CSE 2105 · Data Structures', 74], ['MATH 2101 · Linear Algebra', 61]], ''))}${card('Most dreaded', 'thumbs-down', pollList([['EEE 1241 · Circuits', 68], ['MATH 3201 · Numerical', 55], ['HUM 3201 · Economics', 39]], 'rose'))}</div>`;
    else b = card('Prerequisite flow', 'git-branch', `<div class="prereq">${[['CSE 1101', 'Structured Programming'], ['CSE 1201', 'OOP'], ['CSE 2101', 'Data Structures'], ['CSE 2201', 'Algorithms'], ['CSE 3201', 'Operating Systems'], ['CSE 4100', 'Thesis']].map(([c, n], i) => `<div class="pnode ${i < 4 ? 'done' : i === 4 ? 'now' : ''}" data-act="toast" data-msg="${c}: ${n}"><b>${c}</b><span>${n}</span></div>${i < 5 ? `<span class="parrow">${I('arrow-right', 16)}</span>` : ''}`).join('')}</div><div class="row wrap" style="margin-top:14px"><span class="chip green">Completed</span><span class="chip amber">Current</span><span class="chip">Upcoming</span></div>`);
    return hero({ icon: 'chart-column', eyebrow: 'Results & analytics', a: 'Grade', b: 'Lab', sub: 'CGPA calculator, semester trends and course insights.', side: `<span class="chip amber" style="height:30px;padding:0 12px">${I('graduation-cap', 13)}CGPA 3.62</span>` }) + tabs('/gradelab', GT, sub) + b;
  }
  const pollList = (l, tone) => `<div class="list">${l.map(([n, v]) => `<div class="list-row" data-act="toast" data-msg="Vote counted" style="cursor:pointer"><div class="grow"><div class="row between"><span class="t">${n}</span><b class="num">${v}%</b></div><div style="margin-top:7px">${bar(v, tone)}</div></div></div>`).join('')}</div>`;
  document.addEventListener('change', (e) => {
    if (!e.target.classList.contains('gsel')) return;
    const c = D.courses[+e.target.dataset.i]; c.grade = e.target.value;
    e.target.closest('tr').querySelector('.gp').textContent = GP[c.grade].toFixed(2);
    const g = document.getElementById('gpa'); g.textContent = gpa(); g.animate([{ transform: 'scale(1.15)' }, { transform: 'none' }], 250);
    document.getElementById('cg').textContent = ((3.62 * 98 + +gpa() * 15.5) / 113.5).toFixed(2);
  });
  register({ path: '/gradelab', title: 'GradeLab', group: 'Academics', icon: 'chart-column', render: gradelab });

  /* ───────────── Resource Vault ───────────── */
  const VT = [{ id: 'materials', label: 'Course Materials', icon: 'folder' }, { id: 'notebook', label: 'Notebook', icon: 'notebook-pen' }, { id: 'batch-drive', label: 'Batch Drive', icon: 'lock' }, { id: 'drive-links', label: 'Drive Links', icon: 'link' }, { id: 'carbon-vault', label: 'Carbon Vault', icon: 'code' }, { id: 'code-generate', label: 'Code Generate', icon: 'wand-sparkles' }];
  function vault(sub) {
    sub = sub || 'materials'; let b;
    if (sub === 'materials') b = `<div class="content-card">${sectionHead('folder', 'Resource Vault', 'Course Materials', 'CSE · Year 3 · Semester 2', `<button class="btn sm primary" data-act="upload">${I('upload', 14)}<span>Upload</span></button>`)}<div class="row between wrap" style="margin-bottom:14px">${seg('vc', ['All', 'Slides', 'Notes', 'Questions', 'Lab'], 'All')}<div class="seg"><button class="on">${I('layout-grid', 14)}</button><button>${I('list', 14)}</button></div></div><div class="grid g3">${D.files.map((f) => `<section class="card hoverable file-card" data-act="${f.t === 'folder' ? 'open-folder' : 'preview'}" data-n="${esc(f.n)}"><div class="row between"><span class="ic-tile ${f.t === 'pdf' ? 'rose' : f.t === 'zip' ? 'cyan' : ''}">${I(f.t === 'folder' ? 'folder' : f.t === 'zip' ? 'package' : 'file-text', 18)}</span><button class="icon-btn" data-menu="file">${I('ellipsis-vertical', 15)}</button></div><div class="t" style="font-weight:600;margin:12px 0 4px">${esc(f.n)}</div><div class="row faint" style="font-size:11.5px">${av(f.by, 18, false)}${member(f.by).name.split(' ')[0]} · ${f.c ? f.c + ' files' : '2.4 MB'}</div></section>`).join('')}</div></div>`;
    else if (sub === 'notebook') b = notebook();
    else if (sub === 'carbon-vault') b = `<div class="content-card">${sectionHead('code', 'Resource Vault', 'Carbon Vault', 'Beautiful code snippets for your notes')}<div class="code-card"><div class="row" style="gap:6px;margin-bottom:12px"><i class="dotc"></i><i class="dotc"></i><i class="dotc"></i><span class="faint" style="margin-left:8px;font-size:11px">fork.c</span></div><pre>${esc(`#include <stdio.h>\n#include <unistd.h>\n\nint main(void) {\n    pid_t pid = fork();\n    if (pid == 0) printf("child\\n");\n    else printf("parent of %d\\n", pid);\n    return 0;\n}`)}</pre></div><div class="row" style="justify-content:flex-end;margin-top:12px"><button class="btn" data-act="toast" data-msg="Copied">${I('copy', 14)}Copy</button><button class="btn primary" data-act="toast" data-msg="snippet.png exported">${I('image', 14)}Export PNG</button></div></div>`;
    else b = `<div class="content-card">${sectionHead(VT.find((t) => t.id === sub).icon, 'Resource Vault', VT.find((t) => t.id === sub).label, 'Shared by your batch')}${empty(VT.find((t) => t.id === sub).icon, 'Nothing here yet', 'Be the first to add something for your batch.', `<button class="btn primary sm" data-act="upload">${I('plus', 14)}Add</button>`)}</div>`;
    return hero({ icon: 'book-open', eyebrow: 'Study resources', a: 'Resource ', b: 'Vault', sub: 'Slides, notes, previous questions and code — shared by AUSTians.' }) + tabs('/resource-vault', VT, sub) + b;
  }
  function notebook() {
    return `<div class="nb"><aside class="nb-side card"><div class="row between" style="margin-bottom:10px"><b>Notes</b><button class="icon-btn" data-act="toast" data-msg="New note">${I('plus', 16)}</button></div>${['OS — Scheduling', 'Networks — TCP handshake', 'SE — SOLID principles', 'Numerical — Newton Raphson'].map((n, i) => `<div class="nb-item ${i === 0 ? 'on' : ''}" data-act="nb-pick">${I('sticky-note', 14)}<span>${n}</span></div>`).join('')}</aside>
      <section class="card nb-main"><input class="nb-title" value="OS — Scheduling"><div class="row faint" style="font-size:11px;margin-bottom:12px">${I('clock', 12)}Edited 3 min ago · CSE 3201</div><div class="nb-body" contenteditable="true"><h4>CPU scheduling</h4><ul><li><b>FCFS</b> — simple, convoy effect.</li><li><b>SJF</b> — optimal average waiting time, needs burst prediction.</li><li><b>Round Robin</b> — time quantum q; small q → more context switches.</li></ul><p>Remember: <mark>turnaround = completion − arrival</mark>.</p></div></section></div>`;
  }
  ACTS['nb-pick'] = (el) => { document.querySelectorAll('.nb-item').forEach((x) => x.classList.toggle('on', x === el)); document.querySelector('.nb-title').value = el.textContent.trim(); };
  ACTS['open-folder'] = (el) => modal({ title: el.dataset.n, sub: 'Folder', icon: 'folder', wide: true, body: `<div class="list">${['Lecture 01 — Intro.pdf', 'Lecture 02 — Processes.pdf', 'Lecture 03 — Threads.pdf', 'Lecture 04 — Scheduling.pdf'].map((f) => `<div class="list-row"><span class="ic-tile rose">${I('file-text', 15)}</span><div class="grow"><div class="t">${f}</div><div class="s">1.${Math.floor(Math.random() * 9)} MB</div></div><button class="btn sm" data-act="toast" data-msg="Downloading ${f}">${I('download', 13)}</button></div>`).join('')}</div>`, foot: `<button class="btn" data-close>Close</button><button class="btn primary" data-act="toast" data-msg="Folder zipped">${I('download', 14)}Download all</button>` });
  ACTS.preview = (el) => modal({ title: el.dataset.n, icon: 'file-text', wide: true, body: `<div class="pdf-prev"><div class="paper" style="min-height:300px"><b>Formula sheet</b><div class="paper-line"></div>${'<div class="skel"></div>'.repeat(9)}</div></div>`, foot: `<button class="btn" data-close>Close</button><button class="btn primary" data-act="toast" data-msg="Downloaded">${I('download', 14)}Download</button>` });
  ACTS.upload = () => modal({ title: 'Upload to Vault', icon: 'upload', body: `<div class="empty" style="padding:26px"><span class="ic-tile">${I('upload', 22)}</span><h4>Drop files here</h4><p>PDF, PPT, DOC, ZIP up to 50 MB</p><button class="btn sm">Browse</button></div><div class="form-grid"><div class="field"><span class="label">Course</span><select class="input">${D.courses.map((c) => `<option>${c.code}</option>`)}</select></div><div class="field"><span class="label">Type</span><select class="input"><option>Slides</option><option>Notes</option><option>Questions</option></select></div></div>`, foot: `<button class="btn ghost" data-close>Cancel</button><button class="btn primary" data-save data-msg="Uploaded to Vault">Upload</button>` });
  MENUS.file = [['download', 'Download'], ['bookmark', 'Save'], ['share-2', 'Share link'], ['flag', 'Report', 'danger']];
  register({ path: '/resource-vault', title: 'Resource Vault', group: 'Academics', icon: 'book-open', render: vault });
  register({ path: '/notebook', title: 'Notebook', group: 'Academics', icon: 'notebook-pen', nav: '/resource-vault', hidden: true, render: () => hero({ icon: 'notebook-pen', eyebrow: 'Resource Vault', a: 'Note', b: 'book', sub: 'Your course notes, always synced.' }) + notebook() });

  /* ───────────── Question Bank ───────────── */
  register({ path: '/question-bank', title: 'Question Bank', group: 'Academics', icon: 'file-search', render: (sub) => {
    const topics = [['Process scheduling', 14], ['Deadlocks', 11], ['Paging & segmentation', 10], ['Semaphores', 8], ['File systems', 6], ['Threads', 5]];
    return masthead({ icon: 'file-search', over: 'Academics', title: 'Question Bank Analyzer', sub: 'Find what repeats in previous years', stats: [['Papers', '12'], ['Questions', '186'], ['Topics', '24']], menu: 'qb' }) +
      `<section class="card"><div class="form-grid" style="grid-template-columns:1fr 1fr auto;align-items:end"><div class="field"><span class="label">Course</span><select class="input"><option>CSE 3201 · Operating Systems</option><option>CSE 3203 · Computer Networks</option></select></div><div class="field"><span class="label">Years</span>${seg('qby', ['2019-26', 'Last 3', 'Last 5'], 'Last 5')}</div><button class="btn primary" data-act="qb-run">${I('sparkles', 15)}Analyze</button></div></section>
      <div class="main-grid" id="qbres">${card('Most repeated topics', 'flame', `<div class="list">${topics.map(([t, n], i) => `<div class="list-row"><b class="num faint" style="width:22px">${i + 1}</b><div class="grow"><div class="row between"><span class="t">${t}</span><span class="chip ${i < 2 ? 'amber' : ''}">${n}×</span></div><div style="margin-top:6px">${bar((n / 14) * 100)}</div></div></div>`).join('')}</div>`, `<button class="btn sm" data-act="toast" data-msg="Report sent to printer">${I('printer', 13)}Print</button>`)}
      <div class="stack">${card('Likely this year', 'target', `<div class="list">${['Explain Banker\'s algorithm with an example.', 'Compare FCFS, SJF and RR for the given processes.', 'What is thrashing? How to prevent it?'].map((q) => `<div class="list-row"><span class="ic-tile">${I('circle-dot', 14)}</span><div class="grow t" style="white-space:normal;font-weight:500">${q}</div></div>`).join('')}</div>`)}${card('Saved analyses', 'bookmark', `<div class="list">${['CSE 3203 · Networks', 'MATH 3201 · Numerical'].map((x) => `<div class="list-row" style="cursor:pointer" data-act="toast" data-msg="Loaded ${x}"><div class="grow t">${x}</div>${I('chevron-right', 15)}</div>`).join('')}</div>`)}</div></div>`;
  } });
  ACTS['qb-run'] = (el) => { el.innerHTML = `${I('refresh-cw', 15)}Analyzing…`; setTimeout(() => { toast('Analysis ready · 186 questions'); P.render(); }, 900); };
  MENUS.qb = [['upload', 'Upload a paper', '', 'upload'], ['clock', 'History'], ['printer', 'Print report']];

  /* ───────────── InsideAUST ───────────── */
  const CT = [{ id: 'map', label: 'Floor Map', icon: 'map-pin' }, { id: 'library', label: 'Library Pulse', icon: 'library' }, { id: 'canteen', label: 'Canteen Menu', icon: 'utensils' }, { id: 'bus', label: 'Bus Tracker', icon: 'bus' }, { id: 'classroom', label: 'Free Rooms', icon: 'door-open' }];
  let floor = 7;
  function campus(sub) {
    sub = sub || 'map'; let b;
    if (sub === 'map') b = `<div class="content-card">${sectionHead('map-pin', 'InsideAUST', 'Floor Map', 'Tap a room to see what’s happening', seg('floor', ['1', '2', '3', '4', '5', '6', '7', '8'], String(floor)))}<div class="floor">${Array.from({ length: 16 }, (_, i) => { const id = `${floor}${String.fromCharCode(65 + (i >> 2))}0${(i % 4) + 1}`; const busy = (i * 7 + floor) % 3; return `<div class="room ${['free', 'busy', 'soon'][busy]}" data-act="room" data-r="${id}" data-s="${busy}"><b>${id}</b><span>${['Free', 'In class', 'Free at 2pm'][busy]}</span></div>`; }).join('')}<div class="corridor">Corridor · Lift · Stairs</div></div><div class="row wrap" style="margin-top:12px"><span class="chip green">Free</span><span class="chip rose">In class</span><span class="chip amber">Free soon</span></div></div>`;
    else if (sub === 'library') b = `<div class="grid g3 keep2">${[['Ground floor', 72], ['1st floor', 45], ['Reading room', 91]].map(([f, p]) => `<section class="card"><span class="label">${f}</span><div class="num" style="font-size:2rem;margin:8px 0" >${p}%</div>${bar(p, p > 85 ? 'rose' : '')}<div class="faint" style="font-size:11px;margin-top:8px">${p > 85 ? 'Almost full' : 'Seats available'}</div></section>`).join('')}</div>${card('Busy hours today', 'chart-column', `<div class="bars">${[10, 18, 40, 66, 80, 92, 74, 60, 70, 55, 30, 15].map((v) => `<i style="height:${v}%"></i>`).join('')}</div><div class="row between faint" style="font-size:11px;margin-top:6px">${['8a', '10a', '12p', '2p', '4p', '6p'].map((x) => `<span>${x}</span>`).join('')}</div>`)}`;
    else if (sub === 'canteen') b = `<div class="row between wrap"><div class="row"><span class="chip green">${I('circle-dot', 11)}Open now</span><span class="faint" style="font-size:12px">Closes 6:00 pm</span></div>${seg('meal2', ['Breakfast', 'Lunch', 'Snacks'], 'Lunch')}</div><div class="grid g3">${[['Chicken Biryani', 120, 'Popular'], ['Khichuri + Egg', 70, ''], ['Beef Tehari', 130, 'Popular'], ['Veg Thali', 60, ''], ['Singara (2 pcs)', 20, ''], ['Lemon Tea', 15, '']].map(([n, p, t]) => `<section class="card hoverable" data-act="toast" data-msg="${n} added to favourites"><div class="food">${I('utensils', 22)}</div><div class="row between" style="margin-top:12px"><b>${n}</b><span class="num ok">৳${p}</span></div>${t ? `<span class="chip amber" style="margin-top:8px">${I('flame', 11)}${t}</span>` : ''}</section>`).join('')}</div>`;
    else if (sub === 'bus') b = `<div class="main-grid">${card('Live shuttles', 'bus', `<div class="list">${[['Route 1 · Uttara', 'Near Banani', 12, 'green'], ['Route 2 · Mirpur', 'At Agargaon', 18, 'amber'], ['Route 3 · Dhanmondi', 'Departed AUST', 0, '']].map(([r, w, m, c]) => `<div class="list-row"><span class="ic-tile ${c}">${I('bus', 16)}</span><div class="grow"><div class="t">${r}</div><div class="s">${w}</div></div><span class="chip ${c}">${m ? m + ' min' : 'Left'}</span></div>`).join('')}</div>`)}${card('Route map', 'map', `<div class="route-map"><svg viewBox="0 0 300 180"><path d="M20 150 C 80 40, 160 160, 280 30" fill="none" stroke="var(--border-primary)" stroke-width="6" stroke-linecap="round"/><path d="M20 150 C 80 40, 160 160, 280 30" fill="none" stroke="var(--accent-amber)" stroke-width="3" stroke-dasharray="6 8" stroke-linecap="round"/><circle cx="20" cy="150" r="7" fill="var(--accent-amber)"/><circle cx="280" cy="30" r="7" fill="var(--accent-emerald)"/><circle class="bus-dot" r="6" fill="var(--text-primary)"><animateMotion dur="8s" repeatCount="indefinite" path="M20 150 C 80 40, 160 160, 280 30"/></circle></svg><div class="row between faint" style="font-size:11px"><span>Uttara</span><span>AUST</span></div></div>`)}</div>`;
    else b = `<section class="card"><div class="form-grid" style="grid-template-columns:1fr 1fr auto;align-items:end"><div class="field"><span class="label">Day</span><select class="input"><option>Wednesday</option></select></div><div class="field"><span class="label">Time</span><select class="input"><option>11:00 - 12:20</option></select></div><button class="btn primary" data-act="toast" data-msg="9 free rooms found">${I('search', 15)}Find</button></div></section><div class="grid g4 keep2">${['7A03', '7B02', '6C01', '6C04', '5A02', '4B03', '3A01', '7D04'].map((r) => `<section class="card hoverable" data-act="room" data-r="${r}" data-s="0"><b style="font-size:1.1rem">${r}</b><div class="faint" style="font-size:11.5px;margin-top:4px">Free till 2:00 pm · 60 seats</div></section>`).join('')}</div>`;
    return hero({ icon: 'map-pin', eyebrow: 'Campus live', a: 'Inside', b: 'AUST', sub: 'Rooms, library crowd, canteen menu and shuttles — right now.' }) + tabs('/insideaust', CT, sub) + b;
  }
  P.ACTS['seg:floor'] = (v) => { floor = +v; P.render(); };
  ACTS.room = (el) => { const s = +el.dataset.s; modal({ title: 'Room ' + el.dataset.r, sub: ['Free right now', 'In class: CSE 3201', 'Free at 2:00 pm'][s], icon: 'door-open', body: `<div class="list">${[['8:00', 'CSE 3201', 'Sec B'], ['9:30', 'CSE 3207', 'Sec B'], ['11:00', '—', ''], ['12:30', 'MATH 3201', 'Sec A']].map(([t, c, x]) => `<div class="list-row"><b class="num" style="width:48px">${t}</b><div class="grow t">${c}</div><span class="faint">${x}</span></div>`).join('')}</div>`, foot: `<button class="btn" data-close>Close</button><button class="btn primary" data-save data-msg="Room booked for group study">Book for study</button>` }); };
  register({ path: '/insideaust', title: 'InsideAUST', group: 'Campus', icon: 'map-pin', render: campus });
})();
